parameters.jsCode:
const form = $input.first().json;
const githubUrl = String(form.github_url || '').trim();
const shown = (u) => decodeURIComponent(u).replace(/^https?:\/\//i, '');

if (!githubUrl) {
  return [{ json: { ...form, github_url: '', workflow_structure: '' } }];
}

const match = githubUrl.match(/^https?:\/\/(?:www\.)?github\.com\/([^/]+)\/([^/]+)\/(blob|tree)\/([^/]+)\/([^?#]+)/i);
if (!match) {
  throw new Error(`GitHub URL must link to a workflow .json file (.../blob/<branch>/<path>.json) or a project folder (.../tree/<branch>/<folder>), got ${shown(githubUrl)}`);
}
const [, owner, repo, kind, branch, rawPath] = match;
const path = rawPath.replace(/\/+$/, '').split('/').map(s => encodeURIComponent(decodeURIComponent(s))).join('/');
const headers = { 'User-Agent': 'n8n-linkedin-content-agent', Accept: 'application/vnd.github+json' };
const request = async (url) => {
  try {
    return await this.helpers.httpRequest({ method: 'GET', url, headers, timeout: 60000 });
  } catch (e) {
    const reason = e.httpCode || (/timeout|ETIMEDOUT|ECONNABORTED/i.test(String(e.message)) ? 'timeout' : 'network error');
    throw new Error(`GitHub fetch failed (${reason}) for ${shown(url)} - check the link exists on the pushed branch and the repo is public`);
  }
};
const parse = (body) => (typeof body === 'string' ? JSON.parse(body) : body);

let files;
if (kind.toLowerCase() === 'blob') {
  files = [{ name: decodeURIComponent(rawPath.split('/').pop()), url: `https://raw.githubusercontent.com/${owner}/${repo}/${branch}/${path}` }];
} else {
  const listing = parse(await request(`https://api.github.com/repos/${owner}/${repo}/contents/${path}?ref=${encodeURIComponent(branch)}`));
  if (!Array.isArray(listing)) throw new Error(`GitHub URL is not a folder - ${shown(githubUrl)}`);
  files = listing
    .filter(f => f.type === 'file' && /\.json$/i.test(f.name))
    .map(f => ({ name: f.name, url: f.download_url }));
}

const workflows = [];
const fetchErrors = [];
for (const file of files) {
  try {
    const wf = parse(await request(file.url));
    if (wf && Array.isArray(wf.nodes)) workflows.push({ file: file.name, wf });
  } catch (e) {
    fetchErrors.push(e.message);
  }
}
if (fetchErrors.length) throw new Error(fetchErrors.join(' | '));
if (!workflows.length) {
  throw new Error(`No n8n workflow JSON found at ${shown(githubUrl)} - link a workflow .json file or a folder containing one, in a public repo`);
}

const shortType = (t) => String(t)
  .replace(/^n8n-nodes-base\./, '')
  .replace(/^@n8n\/n8n-nodes-langchain\./, 'langchain.');
const CORE = new Set(['set', 'if', 'switch', 'code', 'merge', 'noOp', 'filter', 'splitInBatches', 'wait', 'aggregate',
  'splitOut', 'limit', 'sort', 'removeDuplicates', 'dateTime', 'executeWorkflow', 'executeWorkflowTrigger',
  'respondToWebhook', 'stopAndError', 'errorTrigger', 'manualTrigger', 'scheduleTrigger', 'webhook', 'formTrigger',
  'form', 'html', 'markdown', 'xml', 'crypto', 'compareDatasets', 'summarize', 'renameKeys', 'itemLists', 'function',
  'functionItem', 'extractFromFile', 'convertToFile', 'readWriteFile', 'editImage', 'httpRequest', 'httpRequestTool']);
const serviceOf = (type) => {
  const s = shortType(type);
  if (s.startsWith('langchain.')) return null;
  const base = s.replace(/(HitlTool|Tool|Trigger)$/, '');
  return CORE.has(s) || CORE.has(base) ? null : base;
};
const modelOf = (n) => {
  const v = n.parameters?.model ?? n.parameters?.modelId ?? n.parameters?.modelName;
  const id = v && typeof v === 'object' ? (v.cachedResultName || v.value) : v;
  return typeof id === 'string' && id && !id.startsWith('=') ? id : null;
};

const summarize = ({ file, wf }) => {
  const nodes = wf.nodes.filter(n => n.type !== 'n8n-nodes-base.stickyNote');
  const triggers = nodes.filter(n => /trigger|webhook/i.test(n.type)).map(n => `${n.name} (${shortType(n.type)})`);
  const models = [...new Set(nodes
    .filter(n => /lmChat|lmOpenAi|embeddings|\.openAi$|anthropic|gemini|mistral|ollama/i.test(n.type))
    .map(n => `${shortType(n.type)}${modelOf(n) ? `: ${modelOf(n)}` : ''}`))];
  const services = [...new Set(nodes.map(n => serviceOf(n.type)).filter(Boolean))];
  const connections = [];
  for (const [source, byType] of Object.entries(wf.connections || {})) {
    for (const [type, outputs] of Object.entries(byType || {})) {
      (outputs || []).forEach((targets, outputIndex) => {
        (targets || []).forEach(t => {
          const label = type !== 'main' ? ` [${type}]` : outputs.length > 1 ? ` (output ${outputIndex + 1})` : '';
          connections.push(`${source} -> ${t.node}${label}`);
        });
      });
    }
  }
  return [
    `Workflow: ${wf.name || file} (file: ${file})`,
    `Triggers: ${triggers.join('; ') || 'none'}`,
    `AI models: ${models.join('; ') || 'none'}`,
    `Services: ${services.join(', ') || 'none'}`,
    `Nodes (${nodes.length}): ${nodes.map(n => `${n.name} [${shortType(n.type)}]`).join('; ')}`,
    `Connections:\n${connections.map(c => `- ${c}`).join('\n') || '- none'}`
  ].join('\n');
};

let workflowStructure = workflows.map(summarize).join('\n\n');
if (workflowStructure.length > 12000) workflowStructure = workflowStructure.slice(0, 12000) + '\n...(truncated)';

return [{ json: { ...form, github_url: githubUrl, workflow_structure: workflowStructure } }];

