const item = $input.first();
const formBinary = $('LinkedIn Post Form').first().binary || {};
const screenshotKey = Object.keys(formBinary).find(k => k.startsWith('workflow_image'));
const binary = { ...(item.binary || {}) };
if (screenshotKey) binary.workflow_image = formBinary[screenshotKey];
return [{ json: { ...item.json, has_workflow_image: Boolean(screenshotKey) }, binary }];

// The Wait resume and data-table step drop binary, so re-attach the exact images shown in the Telegram preview.
const source = $('Attach Workflow Screenshot').first();
return [{
  json: {
    post_text: $('Pick Art Direction').first().json.post_text,
    has_workflow_image: source.json.has_workflow_image === true,
  },
  binary: source.binary,
}];

// One item per image, in post order: generated image first, workflow screenshot second.
const item = $input.first();
return [
  { json: { position: 0, alt_text: 'Illustration for this post' }, binary: { data: item.binary.data } },
  { json: { position: 1, alt_text: 'Screenshot of the n8n workflow' }, binary: { data: item.binary.workflow_image } },
];

// The HTTP response replaces each item, so pair it back with its image binary by index.
const images = $('Split Post Images').all();
return $input.all().map((item, i) => ({
  json: { ...images[i].json, upload_url: item.json.value.uploadUrl, image_urn: item.json.value.image },
  binary: images[i].binary,
}));

// Posts API commentary is 'little text': escape reserved characters so the text is not truncated.
// '#' stays unescaped so hashtags still link.
const escapeLittleText = text => text.replace(/[\\|{}@\[\]()<>*_~]/g, c => '\\' + c);
const images = $('Attach Upload Targets').all()
  .sort((a, b) => a.json.position - b.json.position)
  .map(i => ({ id: i.json.image_urn, altText: i.json.alt_text }));
return [{
  json: {
    body: {
      author: 'urn:li:person:Gkfnk6ftXe',
      commentary: escapeLittleText($('Restore Post Images').first().json.post_text),
      visibility: 'PUBLIC',
      distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] },
      content: { multiImage: { images } },
      lifecycleState: 'PUBLISHED',
      isReshareDisabledByAuthor: false,
    },
  },
}];
